create extension if not exists pgcrypto; create table if not exists properties(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),updated_at timestamptz default now(),address text default '',city text default '',state text default 'UT',zip text default '',source_url text default '',property_type text default 'Multifamily',units integer default 1,beds numeric default 0,baths numeric default 0,sqft numeric default 0,lot_sqft numeric default 0,year_built integer default 0,asking_price numeric default 0,arv numeric default 0,market_rent numeric default 0,section8_rent numeric default 0,rehab numeric default 0,replacement_cost numeric default 0,dom integer default 0,university_miles numeric default 0,taxes_annual numeric default 0,insurance_annual numeric default 0,hoa_monthly numeric default 0,utilities_monthly numeric default 0,market_score numeric default 0,status text default 'New',notes text default '',financing jsonb default '{"ltv":75,"rate":8,"years":30,"points":0}'::jsonb); create table if not exists market_snapshots(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),market_name text not null,state text default '',population_growth numeric,employment_growth numeric,business_growth numeric,rent_growth numeric,home_price_growth numeric,permits_growth numeric,supply_growth numeric,university_growth numeric,momentum_score numeric,source_notes text); create table if not exists comps(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),property_id uuid references properties(id) on delete cascade,comp_type text not null,address text,distance_miles numeric,sale_price numeric,rent_monthly numeric,sqft numeric,beds numeric,baths numeric,sale_date date,source_url text,confidence numeric); create table if not exists underwriting_snapshots(id uuid primary key default gen_random_uuid(),created_at timestamptz default now(),property_id uuid references properties(id) on delete cascade,inputs jsonb not null,outputs jsonb not null);